css:
@font-face {
  font-family: "TH Sarabun Document";
  src: url("/assets/connect_diagnostics_core/fonts/THSarabun.ttf");
  font-style: normal;
  font-weight: 400;
}

@page {
  size: 210mm 297mm;
  margin: 0;
}

html,
body {
  margin: 0 !important;
  padding: 0 !important;
}

.print-format {
  width: 210mm !important;
  min-height: 297mm !important;
  margin: 0 !important;
  margin-top: 0 !important;
  margin-right: 0 !important;
  margin-bottom: 0 !important;
  margin-left: 0 !important;
  padding: 0 !important;
  background: #fff !important;
}

.cd-gr * {
  box-sizing: border-box;
}

.cd-gr.last-page {
  page-break-after: auto;
}

.cd-gr p,
.cd-gr table,
.cd-gr dl,
.cd-gr dt,
.cd-gr dd {
