  font-size: 4.26mm;
}

.cd-gr .field-pair .field-label .label-en {
  line-height: 3.18mm;
  font-size: 3.30mm;
}

.cd-gr .field-value {
  min-width: 0;
  font-size: 4.74mm;
  line-height: 5.16mm;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.cd-gr .receipt-box {
  padding: 3.10mm 3.6mm 2.60mm 3.6mm;
}

.cd-gr .receipt-fields {
  position: relative;
  width: 100%;
  height: 100%;
  display: grid;
  grid-template-columns: 24.5mm 23.0mm 9.5mm minmax(0, 1fr);
  grid-template-rows: 7.4mm 7.4mm 7.4mm 7.4mm 6.5mm;
