}

.cd-gr .document-no-label {
  grid-column: 1;
  grid-row: 1;
}

.cd-gr .document-no {
  font-weight: 700;
  grid-column: 2 / 5;
  grid-row: 1;
}

.cd-gr .document-date-label {
  grid-column: 1;
  grid-row: 2;
}

.cd-gr .document-date-value {
  grid-column: 2 / 5;
  grid-row: 2;
}

.cd-gr .po-label {
  grid-column: 1;
  grid-row: 3;
}

.cd-gr .po-date-label {
  grid-column: 3;
  grid-row: 3;
}

.cd-gr .po-value {
  grid-column: 2;
  grid-row: 3;
  font-size: 4.31mm;
}

.cd-gr .po-date-value {
  grid-column: 4;
  grid-row: 3;
  font-size: 4.02mm;
}

.cd-gr .delivery-label {
  grid-column: 1;
  grid-row: 4;
}

.cd-gr .delivery-value {
  grid-column: 2 / 5;
  grid-row: 4;
}

.cd-gr .lr-label {
  grid-column: 1;
  grid-row: 5;
}

.cd-gr .lr-value {
  grid-column: 2 / 5;
  grid-row: 5;
}

.cd-gr .items-table .col-no {
  width: 6.0%;
}

.cd-gr .items-table .col-description {
  width: 54.5%;
}

.cd-gr .items-table .col-qty {
  width: 17.0%;
}

.cd-gr .items-table .col-rate {
  width: 12.5%;
}

.cd-gr .items-table .col-amount {
  width: 10.0%;
}

.cd-gr .items-table th,
.cd-gr .items-table td {
  border: 0;
  border-right: 0.28mm solid var(--cd-document-border);
}

.cd-gr .items-table th:last-child,
.cd-gr .items-table td:last-child {
  border-right: 0;
}

.cd-gr .items-table thead tr {
  height: 10.90mm;
}

.cd-gr .items-table thead th {
  padding: 1.2mm 1.0mm 0.80mm;
  border-bottom: 0.28mm solid var(--cd-document-border);
  text-align: center;
  vertical-align: middle;
  font-weight: 400;
}

.cd-gr .items-table .cell-no {
  text-align: right;
  padding-right: 2.0mm;
}

.cd-gr .items-table .cell-qty {
  text-align: center;
  white-space: nowrap;
  z-index: 1;
}

.cd-gr .items-table .cell-money {
  text-align: right;
  white-space: nowrap;
  padding-right: 1.55mm;
}

.cd-gr .item-code {
  flex: 0 0 auto;
  white-space: nowrap;
}

.cd-gr .item-name {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.cd-gr .item-meta-piece {
  display: inline-block;
  margin-right: 2.2mm;
}

.cd-gr .qty-uom {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 1.20mm;
  white-space: nowrap;
}

.cd-gr .qty-value,
.cd-gr .uom-text {
  display: inline;
  margin: 0;
  font-size: inherit;
  line-height: inherit;
  white-space: nowrap;
}

.cd-gr .filler-row td {
  padding: 0 !important;
}

.cd-gr.rows-medium .items-table tbody td {
  padding-top: 1.4mm;
  font-size: 4.14mm;
  line-height: 4.38mm;
}

.cd-gr.rows-medium .item-meta-line,
.cd-gr.rows-medium .item-rejected-line,
.cd-gr.rows-medium .received-qty-note {
  font-size: 3.18mm;
  line-height: 3.48mm;
}

.cd-gr.rows-dense .items-table tbody td {
  padding-top: 0.9mm;
  padding-bottom: 0.25mm;
  font-size: 3.72mm;
  line-height: 3.90mm;
}

.cd-gr.rows-dense .item-meta-line,
.cd-gr.rows-dense .item-rejected-line,
.cd-gr.rows-dense .received-qty-note {
  margin-top: 0.25mm;
  font-size: 2.88mm;
  line-height: 3.06mm;
}

.cd-gr .remark-box {
  position: relative;
  padding: 3.0mm 3.0mm;
  border-right: 0.28mm solid var(--cd-document-border);
}

.cd-gr .summary-label .label-th {
  font-size: 4.44mm;
  line-height: 3.72mm;
}

.cd-gr .summary-label .label-en {
  font-size: 3.30mm;
  line-height: 2.82mm;
}

.cd-gr .remark-text {
  margin-top: 2.0mm;
  max-height: 38mm;
  overflow: hidden;
  font-size: 4.14mm;
  line-height: 4.62mm;
}

.cd-gr .totals-box {
  height: 100%;
  display: flex;
  flex-direction: column;
}

.cd-gr .total-row {
  flex: 1 1 0;
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 30.0mm;
  align-items: center;
}

.cd-gr .total-row+.total-row {
  border-top: 0;
}

.cd-gr .total-label {
  position: relative;
  padding: 0.45mm 2.0mm 0.25mm 3.0mm;
}

.cd-gr .total-label .label-th {
  font-size: 4.26mm;
  line-height: 3.54mm;
}

.cd-gr .total-label .label-en {
  font-size: 3.18mm;
  line-height: 2.64mm;
}

.cd-gr .vat-label {
  padding-right: 13mm;
}

.cd-gr .vat-rate {
  position: absolute;
  right: 2.0mm;
  top: 50%;
  transform: translateY(-50%);
  font-size: 3.96mm;
  white-space: nowrap;
}

.cd-gr .grand-total-row {
  min-height: 9.3mm;
  border-top: 0.28mm solid var(--cd-document-border) !important;
}

.cd-gr .grand-total-row .total-label .label-th {
  font-weight: 700;
}

.cd-gr .document-info {
  position: absolute;
  left: 12.70mm;
  top: 55.40mm;
  width: 184.60mm;
  height: 43.10mm;
  display: grid;
  grid-template-columns: 1.31fr 1fr;
  column-gap: 1.55mm;
  page-break-inside: avoid;
}

.cd-gr .receipt-main {
  position: absolute;
  left: 12.70mm;
  top: 100.10mm;
  width: 184.60mm;
  height: 186.15mm;
  border: 0.28mm solid var(--cd-document-border);
  border-radius: 3.0mm;
  overflow: hidden;
  background: #fff;
  page-break-inside: avoid;
}

.cd-gr .items-table {
  width: 100%;
  height: 99.15mm;
  table-layout: fixed;
  border-collapse: collapse;
  border-spacing: 0;
  page-break-inside: avoid;
}

@media print {
  .cd-gr {
    margin: 0 !important;
    box-shadow: none !important;
  }
}

.cd-gr {
  box-sizing: border-box;
  --cd-document-ink: #202020;
  --cd-document-muted: #5f6368;
  --cd-document-border: #202020;
  --cd-document-soft-border: #bdbdbd;
  --cd-document-surface: #f1f1f1;
  --cd-document-accent: #e2a2f5;
  position: relative;
  width: 210mm;
  height: 297mm;
  margin: 0;
  overflow: hidden;
  color: var(--cd-document-ink);
  background: #fff;
  font-weight: 400;
  line-height: 1;
  page-break-after: always;
  -webkit-print-color-adjust: exact;
