  overflow: visible !important;
}

.signature-name {
  margin-top: 16px !important;
  font-size: 2.85mm !important;
  line-height: 3.05mm !important;
  white-space: nowrap !important;
}

.signature-role {
  display: inline !important;
  margin-left: .7mm;
  font-size: 2.65mm !important;
  line-height: 3.05mm !important;
  white-space: nowrap !important;
}

.sign_date {
